-- PT114-S2-Q4. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT114-S2-Q4$batch10$ AND q.stimulus=$batch10$A favorable biography of a politician omits certain incriminating facts about the politician that were available to anyone when the book was written. The book’s author claims that, because he was unaware of these facts when he wrote the book, he is not accountable for the fact that readers were misled by this omission. In a biographer, however, ignorance of this kind cannot be used to evade blame for misleading readers.$batch10$ AND q.prompt=$batch10$Which one of the following principles, if established, does most to justify the position advanced by the passage?$batch10$ AND q.correct_choice=$batch10$E$batch10$) THEN RAISE EXCEPTION 'Question changed: PT114-S2-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT114-S2-Q4$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S2-Q4'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT114-S2-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$The biographer's ignorance can't be used to escape blame for misleading readers.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$The omitted facts were available to anyone when the book was written. The author says not knowing them means not being accountable.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The passage's position is that ignorance is no excuse when the facts were there for anyone to find. The principle should blame a biographer for misleading omissions of facts that were widely available.$batch10$), (3, $batch10$Goal$batch10$, $batch10$A biographer should be blamed for misperceptions caused by omitting facts that were widely available.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT114-S2-Q4$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$Whether readers see the book as favorable isn't the issue. The issue is blame for misleading readers through omission.$batch10$), ($batch10$B$batch10$, $batch10$This blames biographers only when omissions are deliberate. The author says the omission was not deliberate, so this lets the author off.$batch10$), ($batch10$C$batch10$, $batch10$These facts were incriminating, so they wouldn't have supported a favorable view. And this principle excuses authors rather than blaming them.$batch10$), ($batch10$D$batch10$, $batch10$This blames authors only for facts no one else had. The facts here were available to anyone, so the principle clears the author.$batch10$), ($batch10$E$batch10$, $batch10$The facts were widely available, and leaving them out misled readers. This principle says the biographer should be blamed for that, whatever the author knew.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT114-S2-Q4$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
